create index if not exists offers_active_created_idx on public.offers(status,created_at desc); create index if not exists offers_pair_idx on public.offers(source_currency,target_currency,status); create index if not exists offers_owner_idx on public.offers(owner_id,created_at desc); create index if not exists connections_requester_idx on public.connections(requester_id,status,created_at desc); create index if not exists connections_owner_idx on public.connections(offer_owner_id,status,created_at desc); create unique index if not exists connections_pending_unique_idx on public.connections(requester_id,offer_id) where status='pending'; create index if not exists messages_connection_created_idx on public.messages(connection_id,created_at); create index if not exists messages_recipient_read_idx on public.messages(recipient_id,is_read); create index if not exists deals_buyer_idx on public.deals(buyer_id,created_at desc); create index if not exists deals_seller_idx on public.deals(seller_id,created_at desc); create index if not exists subscriptions_user_status_idx on public.subscriptions(user_id,status,expires_at desc); create index if not exists reviews_reviewed_idx on public.reviews(reviewed_user_id,created_at desc);
